<?php
namespace App\Services\Marketing;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class MarketingWhatsAppPreparation {
 private function merchant():string{return app(MarketingPosts::class)->merchant();}
 private function query(int $u){return DB::table('marketing_whatsapp_drafts')->where('merchant_key',$this->merchant())->where('user_id',$u);}
 private function view(object $r):array{return ['id'=>$r->id,'campaign_id'=>$r->campaign_id,'template_id'=>$r->template_id,'template_version'=>(int)$r->template_version,'document'=>json_decode($r->document,true),'status'=>$r->status,'version'=>(int)$r->version];}
 public function listing(int $u):array{return $this->query($u)->orderByDesc('updated_at')->get()->map(fn($r)=>$this->view($r))->all();}
 public function save(int $u,array $d,?string $id):array{return DB::transaction(function()use($u,$d,$id){$r=$id?$this->query($u)->lockForUpdate()->where('id',$id)->first():null;abort_if($id&&!$r,404);abort_unless(($r?(int)$r->version:0)===$d['version'],409,'This message draft changed. Reload before saving.');$campaign=app(MarketingCampaigns::class)->query($u)->findOrFail($d['campaign_id']);abort_unless($campaign->channel==='whatsapp',422,'Choose a WhatsApp campaign. Each campaign uses one channel.');abort_if($campaign->status==='Archived',409,'Restore this campaign before adding content.');$t=app(MarketingContentTemplates::class)->query($u)->findOrFail($d['template_id']);abort_unless($t->channel==='whatsapp'&&!$t->archived_at&&$t->state==='Approved'&&filled($t->provider_id),422,'Choose a Meta-approved WhatsApp template before preparing a campaign.');
  preg_match_all('/\{\{([0-9]+)\}\}/',$t->document['body'],$m);$needed=count(array_unique($m[1]));abort_unless(count($d['values'])===$needed,422,'Provide a value for every message variable.');
  $id=$r?->id??(string)Str::uuid();$doc=['values'=>$d['values'],'timezone'=>$d['timezone'],'scheduled_for'=>$d['scheduled_for']??null];$payload=['campaign_id'=>$campaign->id,'template_id'=>$t->id,'template_version'=>$t->version,'document'=>json_encode($doc,JSON_THROW_ON_ERROR),'version'=>$d['version']+1,'status'=>'Draft','updated_at'=>now()];if($r)$this->query($u)->where('id',$id)->update($payload);else DB::table('marketing_whatsapp_drafts')->insert(['id'=>$id,'merchant_key'=>$this->merchant(),'user_id'=>$u,'created_at'=>now()]+$payload);return $this->view($this->query($u)->where('id',$id)->first());});}
 public function review(int $u,string $id):array {
  $r=$this->query($u)->where('id',$id)->first();abort_unless($r,404);$t=app(MarketingContentTemplates::class)->query($u)->findOrFail($r->template_id);$a=\App\Models\ManagedSocialAccount::where('merchant_key',$this->merchant())->where('platform','whatsapp')->find($t->account_id);$doc=json_decode($r->document,true);$sub=DB::table('marketing_whatsapp_subscriptions')->where('merchant_key',$this->merchant());$eligible=(clone $sub)->where('status','subscribed')->whereNotNull('consented_at')->whereNull('revoked_at')->count();$excluded=(clone $sub)->count()-$eligible;
  $blockers=[];if($t->archived_at)$blockers[]='This template is archived. Restore it or choose another approved template.';if($t->category!=='MARKETING')$blockers[]='Utility templates are for transaction updates. Choose a Marketing template for this campaign.';if(!$a||$a->state!=='connected'||$a->waba_id!==$t->waba_id||$a->app_id!==(string)config('services.whatsapp.app_id'))$blockers[]='Reconnect the business number.';if($t->state!=='Approved')$blockers[]='Use a Meta-approved message template.';if($t->version!==(int)$r->template_version)$blockers[]='The template changed. Save this message again to review the latest version.';if(!$eligible)$blockers[]='No contacts have a recorded WhatsApp marketing subscription.';$blockers[]='A verified sending price is not available yet.';
  $body=$t->document['body'];foreach($doc['values'] as $i=>$v)$body=str_replace('{{'.($i+1).'}}',$v,$body);
  return ['draft'=>$this->view($r),'body'=>$body,'sender'=>$a?->name,'eligible'=>$eligible,'excluded'=>$excluded,'cost'=>null,'can_confirm'=>false,'blockers'=>$blockers,'delivery'=>['sent'=>null,'delivered'=>null,'read'=>null,'failed'=>null],'note'=>'Draft preparation only. No audience has been queued or charged.'];
 }
}
